<?php
declare(strict_types=1);

function migrate_wasooli(): void {
 if(one("SELECT value FROM meta WHERE key='wasooli_version'"))return;
 transaction(function(){
  run('CREATE TABLE IF NOT EXISTS wasooli_collections(id INTEGER PRIMARY KEY AUTOINCREMENT,request_key TEXT NOT NULL UNIQUE,request_hash TEXT NOT NULL,account_id TEXT NOT NULL REFERENCES accounts(id),operator_id INTEGER NOT NULL REFERENCES users(id),actor_id INTEGER NOT NULL REFERENCES users(id),dated TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),cash_account_id TEXT NOT NULL REFERENCES accounts(id),notes TEXT NOT NULL DEFAULT \'\',operator_entry_id INTEGER UNIQUE REFERENCES operator_cash_entries(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)');
  run('CREATE TABLE IF NOT EXISTS wasooli_receipts(collection_id INTEGER NOT NULL REFERENCES wasooli_collections(id),receipt_id INTEGER NOT NULL UNIQUE REFERENCES delivery_cash_receipts(id),PRIMARY KEY(collection_id,receipt_id))');
  run('CREATE INDEX IF NOT EXISTS idx_wasooli_account ON wasooli_collections(account_id,id DESC)');
  run("INSERT OR IGNORE INTO meta(key,value) VALUES('wasooli_version','1')");
 });
}
function wasooli_customer(string $id): array {
 $account=one("SELECT id,name,area,address,mobile,phone,status FROM accounts WHERE id=? AND customer=1",[$id]);if(!$account)throw new InvalidArgumentException('Choose a valid customer.');return $account;
}
function wasooli_list(array $p): array {
 $where=" WHERE a.customer=1 AND a.status='A'";$args=[];$search=text($p,'search',120);if($search!==''){$pattern='%'.str_replace(['\\','%','_'],['\\\\','\\%','\\_'],$search).'%';$where.=" AND (a.name LIKE ? ESCAPE '\\' OR a.id LIKE ? ESCAPE '\\' OR a.area LIKE ? ESCAPE '\\' OR a.mobile LIKE ? ESCAPE '\\' OR a.phone LIKE ? ESCAPE '\\' OR a.mobile2 LIKE ? ESCAPE '\\' OR a.phone2 LIKE ? ESCAPE '\\')";array_push($args,...array_fill(0,7,$pattern));}
 $area=text($p,'area',100);if($area!==''){$where.=' AND a.area=?';$args[]=$area;}
 $total=(int)one('SELECT COUNT(*) n FROM accounts a'.$where,$args)['n'];$page=max(0,min(max(0,(int)ceil($total/30)-1),(int)($p['page']??0)));$sort=match(text($p,'sort',20)){'area'=>"COALESCE(a.area,'') COLLATE NOCASE,a.name COLLATE NOCASE,a.id",'number'=>'a.id',default=>'a.name COLLATE NOCASE,a.id'};
 $rows=query('SELECT a.id,a.name,a.area,a.address,a.mobile,a.phone FROM accounts a'.$where.' ORDER BY '.$sort.' LIMIT 30 OFFSET '.($page*30),$args);
 if($rows){$ids=array_column($rows,'id');$marks=implode(',',array_fill(0,count($ids),'?'));$sums=query("SELECT l.account_id,SUM(MAX(0,l.bilty_due-l.bilty_received)) outstanding,SUM(MAX(0,l.bilty_received-l.bilty_due)) credit,SUM(CASE WHEN l.bilty_due>l.bilty_received THEN 1 ELSE 0 END) bilties FROM delivery_unified_lines l JOIN deliveries d ON d.id=l.delivery_id WHERE l.account_id IN ($marks) AND NOT(d.delivery_mode='walkin' AND NOT EXISTS(SELECT 1 FROM delivery_cash_receipts vr WHERE vr.delivery_id=d.id) AND EXISTS(SELECT 1 FROM cash_collection_submissions vs WHERE vs.delivery_id=d.id AND vs.status='pending')) GROUP BY l.account_id",$ids);$map=array_column($sums,null,'account_id');foreach($rows as &$row){$sum=$map[$row['id']]??[];$row['outstanding']=(int)($sum['outstanding']??0);$row['credit']=(int)($sum['credit']??0);$row['bilties']=(int)($sum['bilties']??0);}unset($row);}
 return ['rows'=>$rows,'total'=>$total,'page'=>$page,'page_size'=>30,'areas'=>query("SELECT DISTINCT area FROM accounts WHERE customer=1 AND status='A' AND TRIM(COALESCE(area,''))<>'' ORDER BY area COLLATE NOCASE")];
}
function wasooli_details(string $account,array $user,int $page=0): array {
 $customer=wasooli_customer($account);$dues=delivery_customer_dues(['account_ids'=>[$account],'details'=>true,'page'=>$page]);$summary=$dues['customers'][0];
 $history=query("SELECT r.id,r.dated,r.date_known,r.created_by,d.reference,SUM(l.bilty_received) amount,group_concat(CASE WHEN l.bilty_received>0 THEN b.bilty END,', ') bilties FROM delivery_cash_receipt_lines l JOIN delivery_cash_receipts r ON r.id=l.receipt_id JOIN deliveries d ON d.id=r.delivery_id JOIN delivery_cash_lines b ON b.delivery_item_id=l.delivery_item_id WHERE b.account_id=? AND l.bilty_received>0 GROUP BY r.id ORDER BY r.dated DESC,r.id DESC LIMIT 30",[$account]);
 $legacyHistory=query("SELECT d.reference,d.dated,di.bilty_received amount,COALESCE(CAST(li.BILLTYNO AS TEXT),i.bilty) bilties,li.REC_DATE received_date FROM deliveries d JOIN delivery_items di ON di.delivery_id=d.id JOIN items i ON i.id=di.item_id LEFT JOIN legacy_IND li ON li.INDNO=di.legacy_id WHERE d.cash_workflow=0 AND i.account_id=? AND di.bilty_received>0 ORDER BY d.dated DESC,di.id DESC LIMIT 30",[$account]);foreach($legacyHistory as $row){$date=substr((string)($row['received_date']??''),0,10);$known=(bool)preg_match('/^\d{4}-\d{2}-\d{2}$/D',$date);$history[]=['id'=>0,'dated'=>$known?$date:$row['dated'],'date_known'=>(int)$known,'created_by'=>'Original record','reference'=>$row['reference'],'amount'=>(int)$row['amount'],'bilties'=>$row['bilties']];}usort($history,fn($a,$b)=>strcmp($b['dated'],$a['dated'])?:((int)$b['id']<=>(int)$a['id']));$history=array_slice($history,0,30);
 $last=one('SELECT l.delivery_id FROM delivery_unified_lines l WHERE l.account_id=? ORDER BY l.delivery_id DESC LIMIT 1',[$account]);
 $operators=[];if($user['role']==='super_admin'){foreach(query("SELECT id,username,full_name FROM users WHERE role='operations' AND active=1 ORDER BY full_name,username") as $operator){$operator['period_token']=operator_cash_token((int)$operator['id']);$operators[]=$operator;}}else $operators[]=['id'=>$user['id'],'username'=>$user['username'],'full_name'=>$user['full_name'],'period_token'=>operator_cash_token((int)$user['id'])];
 return ['customer'=>$customer,'summary'=>$summary,'balance_version'=>$dues['balance_version'],'debts'=>$dues['rows'],'debt_total'=>$dues['total'],'debt_page'=>$dues['page'],'history'=>$history,'has_delivery'=>(bool)$last,'operators'=>$operators,'cash_accounts'=>query("SELECT id,name FROM accounts WHERE status='A' AND (id LIKE '1-101-%' OR id LIKE '1-106-%') ORDER BY id")];
}
function wasooli_save(array $p,array $actor): array {
 $key=text($p,'request_key',100,true);if(!preg_match('/^[a-zA-Z0-9-]{16,100}$/D',$key))throw new InvalidArgumentException('Invalid collection request key.');$hash=shipment_version($p);
 return transaction(function()use($p,$actor,$key,$hash){
  $existing=one('SELECT * FROM wasooli_collections WHERE request_key=?',[$key]);if($existing){if((int)$existing['actor_id']!==(int)$actor['id']||!hash_equals($existing['request_hash'],$hash))throw new RuntimeException('This collection request was already used for different values.',409);return ['id'=>$existing['id'],'amount'=>$existing['amount'],'replayed'=>true];}
  $customer=wasooli_customer(text($p,'account_id',40,true));if($customer['status']!=='A')throw new InvalidArgumentException('Choose an active customer.');$owner=operator_cash_owner($actor,['operator_id'=>(int)($p['operator_id']??0)]);if(!$owner||empty($owner['active'])||$owner['role']!=='operations')throw new InvalidArgumentException('Choose an active munshi.');
  if(!hash_equals(operator_cash_token((int)$owner['id']),text($p,'period_token',100,true)))throw new RuntimeException('The munshi ledger was cleared. Refresh before collecting.',409);
  $amount=money($p,'amount');if(!$amount)throw new InvalidArgumentException('Enter an amount greater than zero.');$dated=day($p);if($dated>date('Y-m-d'))throw new InvalidArgumentException('Collection date cannot be in the future.');$cash=text($p,'cash_account_id',40,true);if(!one("SELECT id FROM accounts WHERE id=? AND status='A' AND (id LIKE '1-101-%' OR id LIKE '1-106-%')",[$cash]))throw new InvalidArgumentException('Choose an active cash or bank account.');
  $debts=delivery_customer_debts([$customer['id']],0);if(!hash_equals(shipment_version($debts),text($p,'balance_version',128,true)))throw new RuntimeException('Customer balances changed. Refresh before collecting.',409);$outstanding=array_sum(array_column($debts,'balance'));if($amount>$outstanding&&empty($p['confirm_credit']))throw new InvalidArgumentException('Confirm the excess customer credit before saving.');
  $remaining=$amount;$targets=[];foreach($debts as $debt){if(!empty($debt['pending_cash']))throw new RuntimeException('A delivery for this customer has cash awaiting approval. Resolve it before collecting.',409);$take=min($remaining,(int)$debt['balance']);if($take){$targets[(int)$debt['delivery_id']][(int)$debt['delivery_item_id']]=($targets[(int)$debt['delivery_id']][(int)$debt['delivery_item_id']]??0)+$take;$remaining-=$take;}if(!$remaining)break;}
  if($remaining){if($targets){$deliveryId=array_key_last($targets);$lineId=array_key_last($targets[$deliveryId]);}else{$last=one("SELECT l.delivery_id,l.delivery_item_id FROM delivery_unified_lines l WHERE l.account_id=? AND NOT EXISTS(SELECT 1 FROM cash_collection_submissions s WHERE s.delivery_id=l.delivery_id AND s.status='pending') ORDER BY l.delivery_id DESC,l.delivery_item_id DESC LIMIT 1",[$customer['id']]);if(!$last)throw new InvalidArgumentException('This customer has no eligible delivered bilty to receive a payment against.');$deliveryId=(int)$last['delivery_id'];$lineId=(int)$last['delivery_item_id'];}$targets[$deliveryId][$lineId]=($targets[$deliveryId][$lineId]??0)+$remaining;}
  $notes=text($p,'notes',500);run('INSERT INTO wasooli_collections(request_key,request_hash,account_id,operator_id,actor_id,dated,amount,cash_account_id,notes) VALUES(?,?,?,?,?,?,?,?,?)',[$key,$hash,$customer['id'],$owner['id'],$actor['id'],$dated,$amount,$cash,$notes]);$collection=(int)db()->lastInsertId();
  foreach($targets as $deliveryId=>$allocation){unified_adopt($deliveryId);$invoice=delivery_cash_invoice($deliveryId);$items=[];foreach($invoice['lines'] as $line)$items[]=['id'=>$line['delivery_item_id'],'bilty_received'=>amount_decimal($allocation[(int)$line['delivery_item_id']]??0),'loading_received'=>'0','suzuki_received'=>'0','legacy_service_received'=>'0'];$receipt=unified_record_cash(['delivery_id'=>$deliveryId,'version'=>$invoice['version'],'request_key'=>'wasooli-'.hash('sha256',$key.'-'.$deliveryId),'dated'=>$dated,'cash_account_id'=>$cash,'notes'=>mb_substr('Daily Wasooli · '.$customer['name'].($notes?' · '.$notes:''),0,500),'items'=>$items],$actor,true,0,false);run('INSERT INTO wasooli_receipts(collection_id,receipt_id) VALUES(?,?)',[$collection,$receipt['id']]);}
  $period=operator_cash_open((int)$owner['id'],true);$title='Daily Wasooli · '.$customer['name'];run("INSERT INTO operator_cash_entries(period_id,operator_id,kind,dated,amount,title,notes,cash_account_id,actor_id,actor_name) VALUES(?,?,'collection',?,?,?,?,?,?,?)",[$period['id'],$owner['id'],$dated,$amount,$title,$notes,$cash,$actor['id'],$actor['username']]);$entry=(int)db()->lastInsertId();run('UPDATE wasooli_collections SET operator_entry_id=? WHERE id=?',[$entry,$collection]);audit('received daily wasooli','wasooli',$collection);
  return ['id'=>$collection,'amount'=>$amount,'credit'=>$remaining,'operator_entry_id'=>$entry];
 });
}
function wasooli_routes(string $action,string $method,array $p,array $user): void {
 if($action==='wasooli_customers'&&$method==='GET')response(wasooli_list($_GET));
 if($action==='wasooli_customer'&&$method==='GET')response(wasooli_details(text($_GET,'account_id',40,true),$user,max(0,(int)($_GET['page']??0))));
 if($action==='wasooli_collect'&&$method==='POST')response(wasooli_save($p,$user),201);
}
